#ifndef BD_LAYERS_UNITS_H_
#define BD_LAYERS_UNITS_H_

#include "../model_config.h"
#include "../types.h"
#include "requant.h"

// Network engine after the stem (PLAN.md phases 3 and 4). One pointwise
// engine, one depthwise engine, one concat/shuffle pass and the head are
// time-multiplexed over the layer program in weights/unit_program.h
// (generated by tools/gen_weights.py): all 16 shuffle units, then conv5 on the
// pointwise engine, then global average pool + fc. Loop bounds come from the
// program at run time.
//
// Feature maps live in on-chip buffers of 8-channel words, HWC order:
// word (pixel p, group g) is at p * groups + g, channel 8g + k in bits
// [8k+7:8k]. That is byte-for-byte the golden tensor layout.
// A "group" below always means one such 8-channel word.
//   X   unit input and output (in place)    T1  pw1 output
//   T2  depthwise output
//   B1, B2  unused since merge-on-write (kept for the generic merge op)
// Downsample unit: b1.dw X->T2, pw1 X->T1, b1.pw T2->X[first half],
//                  dw(s2) T1->T2, pw2 T2->X merged with X[first half]
// Basic unit:      pw1 X[second half]->T1, dw T1->T2,
//                  pw2 T2->X merged with X[first half]
// The merged write puts out[2i] = b1[i], out[2i+1] = b2[i] (concat +
// shuffle) straight into X, so no separate merge pass runs (see unit_pw).
// Head:            conv5 X->T1 (7x7x1024), then GAP + fc on T1 -> NUM_CLASSES
//                  logits.

#define UW 8         // channels per buffer word ("unit word")
#define PW_OUT 16    // pointwise: 8 input x 16 output channels per cycle
#define DW_MAX 56    // widest depthwise input

// Buffer ids used in the src / dst / aux fields of a program layer.
enum { BUF_X = 0, BUF_T1 = 1, BUF_T2 = 2, BUF_B1 = 3, BUF_B2 = 4 };
// Layer kinds: pointwise 1x1, depthwise 3x3, concat + shuffle, GAP + fc.
enum { UL_PW = 0, UL_DW = 1, UL_MERGE = 2, UL_HEAD = 3 };

// One entry of the layer program. Field order must match the initializers
// that tools/gen_weights.py writes into weights/unit_program.h.
struct unit_layer_t {
  unsigned char kind, src, dst, aux; // aux: branch-1 source of a merge
  unsigned char size, stride;        // input size (merge: output size)
  unsigned char cin_g;               // input groups read (merge: half groups)
  unsigned char src_off, src_tot;    // first group read, groups per src pixel
  unsigned char cout_g;              // output groups per pixel
  unsigned short w_base, q_base;     // weight / quant word base
  unsigned char in_signed;           // pw input is int8 (after dw)
  unsigned char merge;               // pw into X: concat + shuffle on write
};

#include "../weights/unit_program.h"

#if UNIT_NUM_CLASSES != NUM_CLASSES
#error "weights/unit_program.h was generated for a different NUM_CLASSES"
#endif

typedef ap_uint<8 * UW> uword_t;             // one feature word, 8 channels
typedef ap_uint<8 * UW * PW_OUT> pw_wword_t; // 128 int8 weights
typedef ap_uint<8 * UW * 9> dw_wword_t;      // 72 int8 weights
typedef ap_uint<64 * 18> pw_qword_t;         // 16 x (bias, M, S)
typedef ap_uint<64 * 9> dw_qword_t;          // 8 x (bias, M, S)
// One fc word holds 8 channels for every class, one 64-bit beat per class:
// class k, channel ch in bits [8 * (UW * k + ch) + 7 : 8 * (UW * k + ch)].
typedef ap_uint<8 * UW * NUM_CLASSES> fc_wword_t;
// fc biases, two INT32 per 64-bit beat: class k in bits [32k + 31 : 32k].
#define FC_B_BEATS ((NUM_CLASSES + 1) / 2)
typedef ap_uint<64 * FC_B_BEATS> fc_bword_t;

// All weight memories of the engine, filled at run time by unit_load_weights.
//   PW_W / DW_W  pointwise / depthwise weights
//   PW_Q / DW_Q  per-channel quant constants (bias, multiplier, shift)
//   FC_W / FC_B  fc weights and the NUM_CLASSES fc biases
#define UNIT_W_PARAMS                                                          \
  pw_wword_t PW_W[UNIT_PW_WORDS], dw_wword_t DW_W[UNIT_DW_WORDS],              \
      pw_qword_t PW_Q[UNIT_QP_WORDS], dw_qword_t DW_Q[UNIT_QD_WORDS],          \
      fc_wword_t FC_W[UNIT_FC_WORDS], fc_bword_t &FC_B
#define UNIT_W_ARGS PW_W, DW_W, PW_Q, DW_Q, FC_W, FC_B

// X is two banks: X[0] holds the even words, X[1] the odd ones (see unit_pw).
#define UNIT_BUF_X_HALF ((UNIT_BUF_X_WORDS + 1) / 2)
#define UNIT_BUF_PARAMS                                                        \
  uword_t X[2][UNIT_BUF_X_HALF], uword_t T1[UNIT_BUF_T1_WORDS],                \
      uword_t T2[UNIT_BUF_T2_WORDS], uword_t B1[UNIT_BUF_B1_WORDS],            \
      uword_t B2[UNIT_BUF_B2_WORDS]
#define UNIT_BUF_ARGS X, T1, T2, B1, B2

// Word access to the banked X by linear word address.
inline uword_t x_read(const uword_t X[2][UNIT_BUF_X_HALF], int addr) {
#pragma HLS INLINE
  return X[addr & 1][addr >> 1];
}
inline void x_write(uword_t X[2][UNIT_BUF_X_HALF], int addr, uword_t v) {
#pragma HLS INLINE
  X[addr & 1][addr >> 1] = v;
}

// Lane accessors for the packed quant words (layout in tools/gen_weights.py):
// LANES 32-bit biases, then LANES 32-bit multipliers, then LANES 8-bit shifts.
template <int LANES, int W>
inline acc_t q_bias(const ap_uint<W> &quant, int lane) {
#pragma HLS INLINE
  return (acc_t)quant.range(32 * lane + 31, 32 * lane);
}
template <int LANES, int W>
inline rq_mult_t q_mult(const ap_uint<W> &quant, int lane) {
#pragma HLS INLINE
  return (rq_mult_t)quant.range(32 * LANES + 32 * lane + 31,
                                32 * LANES + 32 * lane);
}
template <int LANES, int W>
inline rq_shift_t q_shift(const ap_uint<W> &quant, int lane) {
#pragma HLS INLINE
  return (rq_shift_t)quant.range(64 * LANES + 8 * lane + 5,
                                 64 * LANES + 8 * lane);
}

// Reads the run-time weight load image (UNIT_LOAD_WORDS 64-bit words).
// Each memory word is wider than 64 bits, so 64-bit beats are shifted in from
// the top until a whole word is assembled, then stored. Order in the image:
// PW_W, DW_W, PW_Q, DW_Q, FC_W, FC_B.
inline void unit_load_weights(hls::stream<ap_uint<64> > &in, UNIT_W_PARAMS) {
  pw_wword_t pw_word = 0; // 16 beats per word
load_pw_weights:
  for (int i = 0; i < UNIT_PW_WORDS * 16; i++) {
#pragma HLS PIPELINE II = 1
    pw_word = (pw_word >> 64) |
              ((pw_wword_t)in.read() << (pw_wword_t::width - 64));
    if (i % 16 == 15)
      PW_W[i / 16] = pw_word;
  }
  dw_wword_t dw_word = 0; // 9 beats per word
load_dw_weights:
  for (int i = 0; i < UNIT_DW_WORDS * 9; i++) {
#pragma HLS PIPELINE II = 1
    dw_word = (dw_word >> 64) |
              ((dw_wword_t)in.read() << (dw_wword_t::width - 64));
    if (i % 9 == 8)
      DW_W[i / 9] = dw_word;
  }
  pw_qword_t pw_quant = 0; // 18 beats per word
load_pw_quant:
  for (int i = 0; i < UNIT_QP_WORDS * 18; i++) {
#pragma HLS PIPELINE II = 1
    pw_quant = (pw_quant >> 64) |
               ((pw_qword_t)in.read() << (pw_qword_t::width - 64));
    if (i % 18 == 17)
      PW_Q[i / 18] = pw_quant;
  }
  dw_qword_t dw_quant = 0; // 9 beats per word
load_dw_quant:
  for (int i = 0; i < UNIT_QD_WORDS * 9; i++) {
#pragma HLS PIPELINE II = 1
    dw_quant = (dw_quant >> 64) |
               ((dw_qword_t)in.read() << (dw_qword_t::width - 64));
    if (i % 9 == 8)
      DW_Q[i / 9] = dw_quant;
  }
  fc_wword_t fc_word = 0; // NUM_CLASSES beats per word, class 0 first
load_fc_weights:
  for (int i = 0; i < UNIT_FC_WORDS * NUM_CLASSES; i++) {
#pragma HLS PIPELINE II = 1
    fc_word = (fc_word >> 64) |
              ((fc_wword_t)in.read() << (fc_wword_t::width - 64));
    if (i % NUM_CLASSES == NUM_CLASSES - 1)
      FC_W[i / NUM_CLASSES] = fc_word;
  }
  fc_bword_t fc_bias = 0; // FC_B_BEATS beats, classes 0 and 1 in the first
load_fc_bias:
  for (int i = 0; i < FC_B_BEATS; i++) {
#pragma HLS PIPELINE II = 1
    fc_bias = (fc_bias >> 64) |
              ((fc_bword_t)in.read() << (fc_bword_t::width - 64));
  }
  FC_B = fc_bias;
}

// Pointwise 1x1 conv + ReLU requant. One input word (8 channels) per cycle
// against 16 output channels; after cin_g cycles the 16 sums are requantized
// into two output words. Iteration order: pixel, then output pair (16
// channels = 2 output words, highest pair first), then input group.
//
// Destinations:
//   T1          plain write, cout_g words per pixel (pw1, conv5)
//   X, merge=0  plain write into the first half of each X pixel, 2 * cout_g
//               words per pixel (a downsample unit's branch-1 pw)
//   X, merge=1  merge-on-write (a unit's pw2): writes the concat + channel
//               shuffle of (X first half = branch 1, this layer's output)
//               straight into X, in place:
//                 X word byte 2i   = branch-1 channel i
//                 X word byte 2i+1 = this layer's channel i
//               Output pair j (own words 2j, 2j+1) fills X words 4j .. 4j+3
//               and needs branch-1 words 2j, 2j+1, read in the pair's first
//               input cycle. Walking pairs from the highest down, pair j only
//               overwrites X words >= 4j, which no lower pair still reads.
//
// Memory ports. X is stored as two banks, X[0] = even words, X[1] = odd
// words, each a true dual-port RAM. Every X access below uses an explicit
// bank, and each bank sees exactly one read and one write statement per
// iteration, so the loop fits two ports per bank at II = 1:
//   read   the input word (src = X) or branch-1 words 2j, 2j+1 (merge); both
//          start on an even word, so one read per bank covers them
//   write  two words per cycle at most, one per bank: a plain pair writes
//          words 2j, 2j+1; a merged pair writes 4j, 4j+1 in its last input
//          cycle and 4j+2, 4j+3 one cycle later (cin_g >= 2 is required
//          for merge layers so the deferred write never meets the next one)
inline void unit_pw(const unit_layer_t &layer, UNIT_BUF_PARAMS,
                    const pw_wword_t PW_W[UNIT_PW_WORDS],
                    const pw_qword_t PW_Q[UNIT_QP_WORDS]) {
#pragma HLS INLINE off
  const int num_pixels = layer.size * layer.size;
  const int num_out_pairs = (layer.cout_g + 1) / 2; // 16-channel blocks
  const int total_iters = num_pixels * num_out_pairs * layer.cin_g;
  const bool to_x = (layer.dst == BUF_X);
  const bool merge = to_x && layer.merge;
  const int out_stride = to_x ? 2 * layer.cout_g : layer.cout_g;
  acc_t acc[PW_OUT]; // running sums of the 16 output channels
#pragma HLS ARRAY_PARTITION variable = acc complete
  // Every output word is written exactly once, and in merge mode no X word is
  // read after it is overwritten (see above), so there is no real hazard.
#pragma HLS DEPENDENCE variable = X inter false
#pragma HLS DEPENDENCE variable = T1 inter false
  int out_pair = num_out_pairs - 1, in_group = 0;
  int src_base = layer.src_off;  // first input word of the current pixel
  int dst_base = 0;              // first output word of the current pixel
  int w_pair = layer.w_base + out_pair * layer.cin_g; // weights of out_pair
  uword_t b1_lo = 0, b1_hi = 0;  // branch-1 words 2j, 2j+1 (merge only)
  bool pend = false;             // merged words 4j+2, 4j+3 still to write
  int pend_row = 0;              // their bank row
  uword_t pend_0 = 0, pend_1 = 0;
pw_loop:
  for (int i = 0; i < total_iters; i++) {
#pragma HLS PIPELINE II = 1
    // min: stage-4 pw (49 x 6 x 12); max: conv5 (49 x 64 x 24);
    // avg: all pointwise iterations / 36 pointwise layers.
#pragma HLS LOOP_TRIPCOUNT min = 3528 max = 75264 avg = 6794
    // The last pair of an odd cout_g has only one real word.
    const bool has_second = (2 * out_pair + 1 < layer.cout_g);
    const bool last_in = (in_group == layer.cin_g - 1);
    int src_addr = src_base + in_group;

    // X read: one per bank.
    int b1_addr = dst_base + 2 * out_pair; // even
    int rd_row = merge ? (b1_addr >> 1) : (src_addr >> 1);
    uword_t x_even = X[0][rd_row];
    uword_t x_odd = X[1][rd_row];
    if (merge && in_group == 0) {
      b1_lo = x_even;
      b1_hi = x_odd;
    }
    uword_t in_word = (layer.src == BUF_X) ? ((src_addr & 1) ? x_odd : x_even)
                                           : T2[src_addr];
    pw_wword_t weights = PW_W[w_pair + in_group];
    pw_qword_t quant = PW_Q[layer.q_base + out_pair];
    ap_uint<8 * PW_OUT> out_bytes; // 16 requantized outputs
  pw_out_ch:
    for (int oc = 0; oc < PW_OUT; oc++) {
      acc_t partial = 0; // this cycle's 8 products for channel oc
    pw_in_ch:
      for (int ic = 0; ic < UW; ic++) {
        ap_int<9> in_val =
            layer.in_signed
                ? (ap_int<9>)(ap_int<8>)in_word.range(8 * ic + 7, 8 * ic)
                : (ap_int<9>)(ap_uint<8>)in_word.range(8 * ic + 7, 8 * ic);
        ap_int<8> wgt = weights.range(8 * (oc * UW + ic) + 7, 8 * (oc * UW + ic));
        partial += in_val * wgt;
      }
      acc_t sum = (in_group == 0 ? (acc_t)0 : acc[oc]) + partial;
      acc[oc] = sum;
      // Only stored after the last input group, when sum is complete.
      out_bytes.range(8 * oc + 7, 8 * oc) =
          requant_relu(sum + q_bias<PW_OUT>(quant, oc),
                       q_mult<PW_OUT>(quant, oc), q_shift<PW_OUT>(quant, oc));
    }
    uword_t out_lo = out_bytes.range(8 * UW - 1, 0);
    uword_t out_hi = out_bytes.range(16 * UW - 1, 8 * UW);

    // Merged words: word 4j+m interleaves half (m & 1) of branch-1 / own
    // word 2j + m/2.
    uword_t mw[4];
  pw_merge_word:
    for (int m = 0; m < 4; m++) {
      uword_t b1w = (m < 2) ? b1_lo : b1_hi;
      uword_t b2w = (m < 2) ? out_lo : out_hi;
      int half = m & 1;
    pw_merge_byte:
      for (int byte = 0; byte < UW; byte++) {
        int lane = 4 * half + byte / 2;
        mw[m].range(8 * byte + 7, 8 * byte) =
            (byte & 1) ? b2w.range(8 * lane + 7, 8 * lane)
                       : b1w.range(8 * lane + 7, 8 * lane);
      }
    }

    // X write: one per bank.
    bool now = to_x && last_in;
    if (now || pend) {
      int row;
      uword_t w0, w1;
      bool en1;
      if (now && merge) {
        row = (dst_base + 4 * out_pair) >> 1;
        w0 = mw[0];
        w1 = mw[1];
        en1 = true;
      } else if (now) {
        row = (dst_base + 2 * out_pair) >> 1;
        w0 = out_lo;
        w1 = out_hi;
        en1 = has_second;
      } else {
        row = pend_row;
        w0 = pend_0;
        w1 = pend_1;
        en1 = true;
      }
      X[0][row] = w0;
      if (en1)
        X[1][row] = w1;
    }
    pend = now && merge && has_second;
    pend_row = ((dst_base + 4 * out_pair) >> 1) + 1;
    pend_0 = mw[2];
    pend_1 = mw[3];

    // T1 write (pw1, conv5).
    if (!to_x && last_in) {
      int dst_addr = dst_base + 2 * out_pair;
      T1[dst_addr] = out_lo;
      if (has_second)
        T1[dst_addr + 1] = out_hi;
    }

    // Advance (pixel, out_pair descending, in_group).
    if (++in_group == layer.cin_g) {
      in_group = 0;
      if (out_pair == 0) {
        out_pair = num_out_pairs - 1;
        w_pair = layer.w_base + out_pair * layer.cin_g;
        src_base += layer.src_tot; // next pixel
        dst_base += out_stride;
      } else {
        out_pair--;
        w_pair -= layer.cin_g;
      }
    }
  }
  // The very last pair's deferred words.
  if (pend) {
    X[0][pend_row] = pend_0;
    X[1][pend_row] = pend_1;
  }
}

// Depthwise 3x3 (stride 1 or 2, pad 0) + linear INT8 requant. Streams one
// input word per cycle through two line buffers, channel group by channel
// group; an extra row and column of zeros flushes the bottom/right border.
inline void unit_dw(const unit_layer_t &layer, UNIT_BUF_PARAMS,
                    const dw_wword_t DW_W[UNIT_DW_WORDS],
                    const dw_qword_t DW_Q[UNIT_QD_WORDS]) {
#pragma HLS INLINE off
  uword_t line_buf[2][DW_MAX + 1]; // the two previous rows
#pragma HLS ARRAY_PARTITION variable = line_buf dim = 1 complete
#pragma HLS DEPENDENCE variable = line_buf inter false
  uword_t window[3][3]; // current 3x3 window, [row][col]
#pragma HLS ARRAY_PARTITION variable = window complete dim = 0
  const int size = layer.size; // input height == width
  const int groups = layer.cin_g;
  const int out_size = (layer.stride == 2) ? size / 2 : size;
  const int total_iters = groups * (size + 1) * (size + 1);
  int group = 0, y = 0, x = 0;
  dw_wword_t weights = DW_W[layer.w_base];
  dw_qword_t quant = DW_Q[layer.q_base];
dw_loop:
  for (int i = 0; i < total_iters; i++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 768 max = 9747 avg = 3000
    bool in_bounds = (y < size) && (x < size);
    uword_t px = in_bounds
                     ? ((layer.src == BUF_X) ? x_read(X, (y * size + x) * groups + group)
                                             : T1[(y * size + x) * groups + group])
                     : (uword_t)0;
    // Shift the line buffers and the window by one column.
    uword_t top = (y < 2) ? (uword_t)0 : line_buf[0][x];
    uword_t mid = line_buf[1][x];
    line_buf[0][x] = mid;
    line_buf[1][x] = px;
  dw_shift_window:
    for (int r = 0; r < 3; r++) {
      window[r][0] = window[r][1];
      window[r][1] = window[r][2];
    }
    window[0][2] = top;
    window[1][2] = mid;
    window[2][2] = px;
    if (x == 0) {
      // Column -1 of the next window is padding.
    dw_left_pad:
      for (int r = 0; r < 3; r++)
        window[r][1] = 0;
    }
    // The window centred on (y - 1, x - 1) is complete.
    bool window_ready = (y >= 1) && (x >= 1) &&
                        (layer.stride == 1 || ((y & 1) && (x & 1)));
    if (window_ready) {
      int out_y = (layer.stride == 2) ? (y - 1) / 2 : y - 1;
      int out_x = (layer.stride == 2) ? (x - 1) / 2 : x - 1;
      uword_t out_word;
    dw_channel:
      for (int ch = 0; ch < UW; ch++) {
        acc_t acc = q_bias<UW>(quant, ch);
      dw_tap:
        for (int tap = 0; tap < 9; tap++) {
          ap_uint<8> in_val = window[tap / 3][tap % 3].range(8 * ch + 7, 8 * ch);
          ap_int<8> wgt = weights.range(8 * (ch * 9 + tap) + 7, 8 * (ch * 9 + tap));
          acc += (ap_int<17>)(in_val * wgt);
        }
        out_word.range(8 * ch + 7, 8 * ch) =
            requant_linear(acc, q_mult<UW>(quant, ch), q_shift<UW>(quant, ch));
      }
      T2[(out_y * out_size + out_x) * groups + group] = out_word;
    }
    // Advance (group, y, x); load the next group's weights after a full map.
    if (++x == size + 1) {
      x = 0;
      if (++y == size + 1) {
        y = 0;
        if (++group < groups) {
          weights = DW_W[layer.w_base + group];
          quant = DW_Q[layer.q_base + group];
        }
      }
    }
  }
}

// Concat + channel shuffle into X: out[2i] = b1[i], out[2i+1] = b2[i].
// Output word k of a pixel takes half of b1 word k/2 and of b2 word k/2.
// For a basic unit b1 is the first half of X itself, so each pixel is written
// from its last word down: word k only reads word k/2 <= k, never one that
// was already overwritten.
inline void unit_merge(const unit_layer_t &layer, UNIT_BUF_PARAMS) {
#pragma HLS INLINE off
#pragma HLS DEPENDENCE variable = X inter false
  const int num_pixels = layer.size * layer.size;
  const int total_iters = num_pixels * layer.cout_g;
  int pixel = 0, out_idx = layer.cout_g - 1; // out_idx counts down
  int b1_base = 0, b2_base = 0, out_base = 0; // pixel start in each buffer
merge_loop:
  for (int i = 0; i < total_iters; i++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 1176 max = 4704 avg = 2500
    int src_idx = out_idx >> 1; // source word in b1 and b2
    int half = out_idx & 1;     // which 4 channels of that word
    uword_t b1_word = (layer.aux == BUF_X) ? x_read(X, b1_base + src_idx)
                                           : B1[b1_base + src_idx];
    uword_t b2_word = B2[b2_base + src_idx];
    uword_t out_word;
  merge_interleave:
    for (int byte = 0; byte < UW; byte++) {
      int lane = 4 * half + byte / 2;
      // Even output bytes from branch 1, odd ones from branch 2.
      out_word.range(8 * byte + 7, 8 * byte) =
          (byte & 1) ? b2_word.range(8 * lane + 7, 8 * lane)
                     : b1_word.range(8 * lane + 7, 8 * lane);
    }
    x_write(X, out_base + out_idx, out_word);
    if (out_idx == 0) {
      out_idx = layer.cout_g - 1;
      b1_base += layer.src_tot;
      b2_base += layer.cin_g;
      out_base += layer.cout_g;
      pixel++;
    } else {
      out_idx--;
    }
  }
}

// Global average pool (INT32 sum over the 7x7 map; 1/49 is folded into the fc
// scale) and fc 1024 -> NUM_CLASSES with raw INT32 logits, as in the golden
// model.
inline void unit_head(const unit_layer_t &layer, UNIT_BUF_PARAMS,
                      const fc_wword_t FC_W[UNIT_FC_WORDS],
                      const fc_bword_t &FC_B,
                      logit_t logits[NUM_CLASSES]) {
#pragma HLS INLINE off
  // 49 x 8 uint8 values per lane fit in 14 bits.
  ap_uint<16> gap[UNIT_FC_WORDS][UW]; // per-channel sums over all pixels
#pragma HLS ARRAY_PARTITION variable = gap dim = 2 complete
#pragma HLS DEPENDENCE variable = gap inter false
  const int groups = layer.cin_g;
  const int total_iters = layer.size * layer.size * groups;
  int pixel = 0, group = 0;
head_gap_loop:
  for (int i = 0; i < total_iters; i++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 6272 max = 6272
    // Same group again only groups (= 128) iterations later, so no real hazard.
    uword_t in_word = T1[i];
  head_gap_channel:
    for (int ch = 0; ch < UW; ch++)
      gap[group][ch] = (pixel == 0 ? (ap_uint<16>)0 : gap[group][ch]) +
                       (ap_uint<8>)in_word.range(8 * ch + 7, 8 * ch);
    if (++group == groups) {
      group = 0;
      pixel++;
    }
  }
  acc_t acc_class[NUM_CLASSES]; // one running sum per class
#pragma HLS ARRAY_PARTITION variable = acc_class complete
head_fc_init:
  for (int k = 0; k < NUM_CLASSES; k++)
    acc_class[k] = (acc_t)FC_B.range(32 * k + 31, 32 * k);
head_fc_loop:
  for (int g = 0; g < groups; g++) {
#pragma HLS PIPELINE II = 1
#pragma HLS LOOP_TRIPCOUNT min = 128 max = 128
    fc_wword_t fc_weights = FC_W[g]; // class k in bits [64k + 63 : 64k]
  head_fc_class:
    for (int k = 0; k < NUM_CLASSES; k++) {
    head_fc_channel:
      for (int ch = 0; ch < UW; ch++) {
        ap_int<17> gap_val = gap[g][ch];
        acc_class[k] += gap_val * (ap_int<8>)fc_weights.range(
                                      8 * (UW * k + ch) + 7, 8 * (UW * k + ch));
      }
    }
  }
head_fc_out:
  for (int k = 0; k < NUM_CLASSES; k++)
    logits[k] = acc_class[k];
}

// Runs one program layer. The head writes logits.
inline void unit_layer(const unit_layer_t &layer, UNIT_BUF_PARAMS,
                       UNIT_W_PARAMS, logit_t logits[NUM_CLASSES]) {
#pragma HLS INLINE
  if (layer.kind == UL_PW)
    unit_pw(layer, UNIT_BUF_ARGS, PW_W, PW_Q);
  else if (layer.kind == UL_DW)
    unit_dw(layer, UNIT_BUF_ARGS, DW_W, DW_Q);
  else if (layer.kind == UL_MERGE)
    unit_merge(layer, UNIT_BUF_ARGS);
  else
    unit_head(layer, UNIT_BUF_ARGS, FC_W, FC_B, logits);
}

// Runs program layers [0, n_layers).
inline void unit_run(int n_layers, UNIT_BUF_PARAMS, UNIT_W_PARAMS,
                     logit_t logits[NUM_CLASSES]) {
layer_loop:
  for (int layer_idx = 0; layer_idx < n_layers; layer_idx++) {
#pragma HLS LOOP_TRIPCOUNT min = 1 max = 72 avg = 72
    unit_layer_t layer = UNIT_PROGRAM[layer_idx];
    unit_layer(layer, UNIT_BUF_ARGS, UNIT_W_ARGS, logits);
  }
}

#endif // BD_LAYERS_UNITS_H_
